import{_ as e,o as r,c as o,a2 as t}from"./chunks/framework.BjkiRu3Q.js";const i="/images/admin/facturacion-pdf.webp",f=JSON.parse('{"title":"6. Cómo Imprimir Facturas y Hacer Anulaciones","description":"","frontmatter":{},"headers":[],"relativePath":"admin/facturacion.md","filePath":"admin/facturacion.md"}'),s={name:"admin/facturacion.md"};function n(l,a,c,d,u,m){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="_6-como-imprimir-facturas-y-hacer-anulaciones" tabindex="-1">6. Cómo Imprimir Facturas y Hacer Anulaciones <a class="header-anchor" href="#_6-como-imprimir-facturas-y-hacer-anulaciones" aria-label="Permalink to &quot;6. Cómo Imprimir Facturas y Hacer Anulaciones&quot;">​</a></h1><p>El módulo de <strong>Facturación</strong> (<a href="https://pyme.rsfsecure.site/admin/facturas" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/admin/facturas</a>) te permite generar e imprimir facturas con formato fiscal válido para Panamá con el <strong>7% de ITBMS</strong> desglosado, tanto en formato carta para oficina como en ticket térmico para paquetería.</p><hr><h2 id="_6-1-como-ver-e-imprimir-una-factura" tabindex="-1">6.1 Cómo ver e imprimir una Factura <a class="header-anchor" href="#_6-1-como-ver-e-imprimir-una-factura" aria-label="Permalink to &quot;6.1 Cómo ver e imprimir una Factura&quot;">​</a></h2><p>Cada vez que un pedido pasa al estado <strong>Pagado</strong>, el sistema genera automáticamente su factura correspondiente:</p><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Vista de Factura Fiscal para Imprimir</span><span class="screenshot-url">https://pyme.rsfsecure.site/admin/facturas/...</span></div><div class="screenshot-body"><img src="'+i+'" alt="Vista de Factura Fiscal para Imprimir" loading="lazy" decoding="async"></div></div><h3 id="tienes-dos-formatos-disponibles" tabindex="-1">Tienes dos formatos disponibles: <a class="header-anchor" href="#tienes-dos-formatos-disponibles" aria-label="Permalink to &quot;Tienes dos formatos disponibles:&quot;">​</a></h3><ol><li><strong>Factura Completa (PDF Carta/A4):</strong></li></ol><ul><li>Es el formato tradicional con todos los datos legales.</li><li>Ideal para clientes comerciales, reclamos de garantía o para archivar en tu contabilidad.</li></ul><ol start="2"><li><strong>Ticket Térmico (80mm o 58mm):</strong></li></ol><ul><li>Diseñado para impresoras de punto de venta (las impresoras pequeñas de rollo).</li><li>Es el que se suele grapar o pegar por fuera de la caja o sobre del paquete para la entrega rápida.</li></ul><hr><h2 id="_6-2-como-anular-una-factura-o-devolver-una-venta" tabindex="-1">6.2 Cómo Anular una Factura o Devolver una Venta <a class="header-anchor" href="#_6-2-como-anular-una-factura-o-devolver-una-venta" aria-label="Permalink to &quot;6.2 Cómo Anular una Factura o Devolver una Venta&quot;">​</a></h2><p>Si un cliente canceló su pedido antes de salir de bodega, o si hubo una devolución justificada:</p><ol><li>Entra a la factura en el panel administrativo.</li><li>Haz clic en el botón rojo <strong>&quot;Anular Factura / Nota de Crédito&quot;</strong>.</li><li>El sistema te pedirá escribir el <strong>Motivo de la Anulación</strong> (por ejemplo: <em>&quot;Cliente solicitó cancelación antes del envío&quot;</em>).</li><li>Confirma la anulación.</li><li><strong>¿Qué hace el sistema automáticamente?</strong></li></ol><ul><li>Las unidades vendidas regresan de inmediato al inventario disponible para que otro cliente pueda comprarlas.</li><li>La factura queda registrada como Anulada en tus reportes para mantener tu cuadre de caja transparente.</li></ul>',16)])])}const h=e(s,[["render",n]]);export{f as __pageData,h as default};
